class Ledger {
  private bal: number[];
  constructor(balances: number[]) {
    this.bal = [...balances];
  }

  private valid(a: number): boolean {
    return a >= 1 && a <= this.bal.length;
  }

  move(from: number, to: number, amount: number): boolean {
    if (!this.valid(from) || !this.valid(to) || this.bal[from - 1] < amount) return false;
    this.bal[from - 1] -= amount;
    this.bal[to - 1] += amount;
    return true;
  }

  credit(account: number, amount: number): boolean {
    if (!this.valid(account)) return false;
    this.bal[account - 1] += amount;
    return true;
  }

  debit(account: number, amount: number): boolean {
    if (!this.valid(account) || this.bal[account - 1] < amount) return false;
    this.bal[account - 1] -= amount;
    return true;
  }
}

