class Ledger {
  private bal = new Map<number, number>();
  constructor(balances: number[]) {
    balances.forEach((b, i) => this.bal.set(i + 1, b));
  }

  credit(account: number, amount: number): boolean {
    const b = this.bal.get(account);
    if (b === undefined) return false;
    this.bal.set(account, b + amount);
    return true;
  }

  debit(account: number, amount: number): boolean {
    const b = this.bal.get(account);
    if (b === undefined || b < amount) return false;
    this.bal.set(account, b - amount);
    return true;
  }

  move(from: number, to: number, amount: number): boolean {
    if (!this.bal.has(to)) return false; // check before the debit so nothing changes on failure
    return this.debit(from, amount) && this.credit(to, amount);
  }
}

